def prepare_url(self, url, params):
    """Prepares the given HTTP URL."""
    if isinstance(url, bytes):
        url = url.decode('utf8')
    url = url.strip()
    if not url:
        raise MissingSchema('Invalid URL {0!r}: No schema supplied'.format(url))
    if ':' in url and not url.lower().startswith('http'):
        self.url = url
        return

